/**
 * Years of Faithfulness
 * ---------------------
 * Three hundred years of small, repeated acts — teaching, tending, giving — with no fanfare. Stage: the changing seasons of a single street: sowing, harvest, rain, repair; the same figure walking the road; light shifting from spring gold to autumn amber.
 *
 * Palette 0x1a1024 → 0x060402 · light: dawn · hero: pillar
 *
 * Generated by scripts/add-shot-scenes.mjs from the act data and
 * the mood board in ../../art/. Composition follows the kit in
 * ./enoch-kit.js.
 */

import { THREE, createScene, cityGate, house, wheat, rain, well, pillar, person, birds } from './enoch-kit.js';

const BG = 0x1a1024;
const GROUND = 0x060402;

export function build(group) {
    const W = createScene(group, { seed: 375673549, bg: BG, fogNear: 55, fogFar: 220 });

    /* light — dawn */
    W.lights({ sky: 0x9ab4d0, gnd: 0x5a5a52, hemi: 0.75, sun: 0xffd9a0, sunI: 0.95, sunPos: [-45, 16, 26] });

    W.disc([-58, 30, -145], 9, 0xffd9a0);
    W.disc([-58, 30, -155], 16, 0xffb060, 0.22);
    W.stars(60, 150, [0xcfd8e8, 0xbfd0e0], 0.55);
    const clouds = W.grp(group, [0, 0, 0], { name: 'cloud_bank' });
    [[-60, 34, -120, 24], [10, 40, -135, 30], [70, 33, -125, 22]].forEach(([x, y, z, s]) => {
        W.add(clouds, W.G('ico', 1, 1), W.mat(0xd8c8b8, { opacity: 0.5 }), [x, y, z], { s: [s, s * 0.24, s * 0.5] });
    });
    W.backdrop(clouds);

    /* ground */
    W.ground(260, 260, 0, 0, 0x060402, { amp: 0.6, j: 0.3, flat: 30, rise: (x, z) => Math.sin(x * 0.05) * Math.cos(z * 0.04) * 1.2 });

    /* city: gate, towers and houses on the far side */
    const city = W.grp(group, [-18, 0, -58], { name: 'city', r: [0, -0.14, 0] });
    cityGate(W, city, 0, 0, 0, 1.15, { stone: 0x060402, trim: 0x050302 });
    for (let i = 0; i < 5; i++) {
        house(W, city, -34 + i * 17 + W.rr(-4, 4), 0, W.rr(-14, 6), 0.85 + W.r() * 0.4, { mud: 0x060402 });
    }
    W.backdrop(city);

    /* fields: standing grain to the horizon */
    wheat(W, group, 0, 34, 220, 110, { h: 2.1, stalk: 0x1d1228, head: 0x21142d });

    /* storm: rain sheets across the whole frame */
    rain(W, group, 900, 230, 65, 16);

    well(W, group, -4.5, 0, -5.5, );
    /* gold: glints of treasure in the dust */
    for (let i = 0; i < 14; i++) W.add(group, W.G('oct', 0.14), W.mat(0xe8c050, { metal: 0.6, rough: 0.3, emissive: 0x4a3008, ei: 0.3 }), [W.rr(-20, 20), 0.1, W.rr(-14, 14)], { s: [1, 0.5, 1] });

    /* hero: the standing stone */
    pillar(W, group, 0, 0, 0, 1.15, { stone: 0x060402 });
    W.disc([0, 6, -12], 5, 0x22152f, 0.3);

    /* figures */
    person(W, group, [-5, 0, 5], { robe: 0x1a1024, bend: 0.2, armR: [0.35, 0.1], armL: [-0.35, -0.1], ry: -0.02, s: 1.05 });
    person(W, group, [4.5, 0, 6], { robe: 0x060402, bend: 0.2, armR: [0.35, 0.1], armL: [-0.35, -0.1], ry: -0.70, s: 1.05 });
    person(W, group, [1, 0, -5], { robe: 0x8a6a44, bend: 0.2, armR: [0.35, 0.1], armL: [-0.35, -0.1], ry: 0.60, s: 1.18 });

    /* birds: slow circles high above */
    birds(W, group, 8, 55, { y: 26 });

    return W.finish();
}

export default { build };
